toolCalls.commandLine:
python -c "import subprocess,pathlib,sys; ref=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip(); cases=['3 + 4','1 + 2 * 3','(1 + 2) * 3','5 mod 2','5.25 mod 2','3 ** 3','10 / 4','10 // 4','1 == 1','true and false','not false','\"abc\" =~ \"b\"','\"a\" in \"abc\"','[1, 2, 3] | get 1','[1, 2, 3] | length','[1, 2, 3] | first','[3, 1, 2] | sort | to json -r','[a, B, d, C, f] | sort -i | to json --raw','1..5 | math sum','1..5 | where $it > 3 | to json -r','[[a b]; [jim susie] [3 4]] | to json -r','[[a b]; [jim susie] [3 4]] | get a.0','[[a b]; [jim susie] [3 4]].b.1','[[name, age]; [paul, 21]] | columns | get 0','[[name, age]; [paul, 21]] | reject age | to json -r','\"hello world\" | split row \" \" | get 1','\"hello world\" | split column \" \" | get column1.0','\"a-b-c\" | str replace \"-\" \"+\"','\"abc\" | str length','\"AbC\" | str downcase','[a b c] | str join \"-\"','char nl | str length','{foo: 3, bar: \"x\"} | to json -r','[[a b]; [1 2]] | to csv','[1,2,3] | to nuon','null | to nuon','pwd','ls | length','path exists REFERENCE_BINARY.txt'];
for c in cases:
 r=subprocess.run([ref,'-c',c],capture_output=True); p=subprocess.run(['python','nushell_port.py','-c',c],capture_output=True); ok=(r.returncode,p.returncode,r.stdout,p.stdout,r.stderr,p.stderr); match=(r.returncode==p.returncode and r.stdout==p.stdout and r.stderr==p.stderr); print(('OK ' if match else 'BAD ')+c); 
 if not match: print(' ref',r.returncode,repr(r.stdout.decode(errors='replace')),repr(r.stderr.decode(errors='replace')[:200])); print(' port',p.returncode,repr(p.stdout.decode(errors='replace')),repr(p.stderr.decode(errors='replace')[:200]))"

